type DownloadFile = { label: string; file: string; size: string; href: string; primary?: boolean };

const sizeFmt = new Intl.NumberFormat("es", { maximumFractionDigits: 1, minimumFractionDigits: 1 });
const asset = (suffix: string, label: string, primary = false): DownloadFile[] => {
  const a = release.assets.find((x) => x.name.endsWith(suffix));
  // A file missing from the release is not offered at all.
  return a ? [{ label, file: a.name, href: a.url, size: `${sizeFmt.format(a.size / 1e6)} MB`, primary }] : [];
};

